const reconcileDeliverableCounters = `-- name: ReconcileDeliverableCounters :exec
UPDATE agent_dlv_deliverable SET
    required_total = (
        SELECT CAST(COUNT(*) AS INTEGER) FROM agent_dlv_deliverable c
        WHERE c.parent_id = agent_dlv_deliverable.id AND c.required = 1
    ),
    required_accepted = (
        SELECT CAST(COUNT(*) AS INTEGER) FROM agent_dlv_deliverable c
        WHERE c.parent_id = agent_dlv_deliverable.id AND c.required = 1
          AND c.lifecycle = 'accepted'
    ),
    required_failed = (
        SELECT CAST(COUNT(*) AS INTEGER) FROM agent_dlv_deliverable c
        WHERE c.parent_id = agent_dlv_deliverable.id AND c.required = 1
          AND c.lifecycle IN ('rejected_final', 'abandoned', 'cancelled')
    ),
    required_blocked = (
        SELECT CAST(COUNT(*) AS INTEGER) FROM agent_dlv_deliverable c
        WHERE c.parent_id = agent_dlv_deliverable.id AND c.required = 1
          AND c.lifecycle = 'blocked'
    ),
    updated_at = datetime('now')
WHERE agent_dlv_deliverable.id = ?
`

func (q *Queries) ReconcileDeliverableCounters(ctx context.Context, id string) error {
	_, err := q.db.ExecContext(ctx, reconcileDeliverableCounters, id)
	return err
}

